-- Northem platform: every migration + seed in one file, for the Supabase SQL editor.
-- Generated by supabase/bundle.sh. Run once on an empty project.

-- >>> migrations/0001_core.sql
-- Northem platform: core tenancy, people and roles.
--
-- One Supabase project serves every Northem app: the landing site, the four
-- division sites, portal and admin. Every business row carries org_id so the
-- same database can host other production houses later (whitelabel). Northem
-- is simply the first org.
--
-- Roles are Postgres enums on purpose: enum values compare by declaration
-- order, so "role >= 'crew'" reads the way it sounds. Never reorder them;
-- add new values with ALTER TYPE ... ADD VALUE ... BEFORE/AFTER.

-- Supabase keeps pgcrypto in the "extensions" schema; functions that hash
-- tokens put it on their search_path.
create extension if not exists pgcrypto;
create extension if not exists citext;

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------

-- Org-wide role. UI labels: Guest, Press, Cast, Crew, Director / producer, Admin, Owner.
create type org_role as enum ('guest', 'press', 'cast', 'crew', 'producer', 'admin', 'owner');

-- Role inside one project. 'head' is a head of department, 'lead' runs the
-- project (director, producer, project lead). Org admins act as 'lead' everywhere.
create type project_role as enum ('guest', 'cast', 'crew', 'head', 'lead');

create type member_status as enum ('active', 'suspended', 'left');

create type project_visibility as enum (
  'private',   -- project members only
  'internal',  -- everyone in the org
  'unlisted',  -- public page reachable by link, not listed
  'public'     -- listed on the division site and searchable
);

-- ---------------------------------------------------------------------------
-- Shared trigger: updated_at
-- ---------------------------------------------------------------------------

create or replace function set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Orgs (tenants)
-- ---------------------------------------------------------------------------

create table orgs (
  id uuid primary key default gen_random_uuid(),
  slug citext not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,40}$'),
  name text not null,
  -- Whitelabel branding for portal/admin: logo, colours, product name, mail sender.
  branding jsonb not null default '{}'::jsonb,
  settings jsonb not null default '{}'::jsonb,
  plan text not null default 'internal',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger orgs_updated before update on orgs for each row execute function set_updated_at();

-- Which host belongs to which org and which app, so one deployment can serve
-- portal.northem.group and intranet.someotherstudio.com alike.
create table org_domains (
  host citext primary key,
  org_id uuid not null references orgs(id) on delete cascade,
  app text not null check (app in ('landing', 'division', 'portal', 'admin', 'project')),
  division_id uuid,  -- set for division sites; FK added below
  is_primary boolean not null default false,
  created_at timestamptz not null default now()
);
create index org_domains_org_idx on org_domains(org_id);

-- Divisions: Northem Productions, Northem Development, Specprod, SoNorthem.
-- Each has its own site and theme; another tenant may have none or many.
create table divisions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  slug citext not null,
  name text not null,
  tagline text,
  description text,
  theme jsonb not null default '{}'::jsonb,
  sort int not null default 0,
  is_public boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, slug)
);
create trigger divisions_updated before update on divisions for each row execute function set_updated_at();
alter table org_domains add constraint org_domains_division_fk
  foreign key (division_id) references divisions(id) on delete set null;

-- ---------------------------------------------------------------------------
-- Profiles: one per auth user, owned and customised by that user.
-- Email lives only in auth.users and is never exposed through this table.
-- ---------------------------------------------------------------------------

create table profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  handle citext unique check (handle ~ '^[a-z0-9][a-z0-9_.-]{1,30}$'),
  display_name text not null default '',
  headline text,               -- "Gaffer, cold-weather specialist"
  bio text,
  avatar_url text,
  cover_url text,
  location text,
  links jsonb not null default '[]'::jsonb,   -- [{label, url}]
  theme jsonb not null default '{}'::jsonb,   -- their own profile page theme
  is_public boolean not null default true,
  onboarded_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger profiles_updated before update on profiles for each row execute function set_updated_at();

-- Every new auth user gets a profile row.
create or replace function handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', ''))
  on conflict (id) do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function handle_new_user();

-- ---------------------------------------------------------------------------
-- Org membership and permissions
-- ---------------------------------------------------------------------------

create table org_members (
  org_id uuid not null references orgs(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role org_role not null default 'guest',
  title text,                                   -- "Head of Development"
  departments text[] not null default '{}',     -- camera, sound, art, dev, ...
  status member_status not null default 'active',
  joined_at timestamptz not null default now(),
  primary key (org_id, user_id)
);
create index org_members_user_idx on org_members(user_id);

-- Capabilities an admin can toggle per role in the admin app. Owners always
-- have every capability, so an org can never lock itself out.
-- Known perms (the admin UI lists these):
--   projects.create  projects.manage_all  people.manage  people.invite
--   forms.read  forms.manage  openings.manage  chat.create_channel
--   chat.moderate  sites.edit  podcasts.publish  integrations.manage
--   roles.manage  audit.read
create table role_permissions (
  org_id uuid not null references orgs(id) on delete cascade,
  role org_role not null,
  perm text not null,
  primary key (org_id, role, perm)
);

-- Defaults for a new org; admins edit from there.
create or replace function seed_role_permissions(p_org uuid) returns void
language sql security definer set search_path = public as $$
  insert into role_permissions (org_id, role, perm)
  select p_org, r::org_role, p from (values
    ('admin', 'projects.create'), ('admin', 'projects.manage_all'), ('admin', 'people.manage'),
    ('admin', 'people.invite'), ('admin', 'forms.read'), ('admin', 'forms.manage'),
    ('admin', 'openings.manage'), ('admin', 'chat.create_channel'), ('admin', 'chat.moderate'),
    ('admin', 'sites.edit'), ('admin', 'podcasts.publish'), ('admin', 'integrations.manage'),
    ('admin', 'audit.read'),
    ('producer', 'projects.create'), ('producer', 'people.invite'), ('producer', 'forms.read'),
    ('producer', 'openings.manage'), ('producer', 'chat.create_channel'), ('producer', 'podcasts.publish'),
    ('crew', 'chat.create_channel')
  ) as d(r, p)
  on conflict do nothing;
$$;

create or replace function orgs_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform seed_role_permissions(new.id);
  return new;
end $$;
create trigger orgs_seed_perms after insert on orgs for each row execute function orgs_after_insert();

-- ---------------------------------------------------------------------------
-- People: anyone who can be credited. A person need not have an account;
-- when they join, their auth profile is linked (profile_id) and they can
-- edit the public parts themselves. Scoped per org so tenants stay apart.
-- ---------------------------------------------------------------------------

create table people (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  slug citext not null check (slug ~ '^[a-z0-9][a-z0-9-]{0,60}$'),
  name text not null,
  known_for text,           -- "Cinematographer", shown under the name
  bio text,
  photo_url text,
  links jsonb not null default '[]'::jsonb,
  profile_id uuid references profiles(id) on delete set null,
  is_public boolean not null default true,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, slug),
  unique (org_id, profile_id)
);
create trigger people_updated before update on people for each row execute function set_updated_at();
create index people_profile_idx on people(profile_id);
create index people_name_fts_idx on people using gin (to_tsvector('simple', name));

-- >>> migrations/0002_projects.sql
-- Projects and everything hanging off them: members, credits, the "real side"
-- of a production (media, bloopers, trivia, diary moments, podcasts),
-- internal documents, and links to Screenplay Studio and Graphite.

create type project_kind as enum (
  'feature', 'short', 'documentary', 'series', 'episode', 'commercial', 'music_video',
  'branded', 'social', 'specialty_shoot',            -- productions, Specprod, SoNorthem
  'website', 'app', 'tool', 'platform', 'game',       -- development
  'other'
);

create type project_status as enum (
  'idea', 'development', 'pre_production', 'production', 'post_production',
  'building', 'beta', 'released', 'live', 'on_hold', 'archived'
);

-- Reusable themes for public project pages, built by hand in admin.
-- tokens: colours, fonts, radii, grain, motion. layout: hero style, section order.
create table themes (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  name text not null,
  tokens jsonb not null default '{}'::jsonb,
  layout jsonb not null default '{}'::jsonb,
  custom_css text,          -- sanitised and scoped server-side before render
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger themes_updated before update on themes for each row execute function set_updated_at();

create table projects (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  division_id uuid references divisions(id) on delete set null,
  slug citext not null check (slug ~ '^[a-z0-9][a-z0-9-]{0,80}$'),
  title text not null,
  kind project_kind not null default 'other',
  status project_status not null default 'idea',
  logline text,
  synopsis text,
  year int,
  release_date date,
  runtime_minutes int,
  locations text[] not null default '{}',
  genres text[] not null default '{}',
  poster_url text,
  cover_url text,
  trailer_url text,
  client text,                       -- for commercial/dev work, shown only if allowed
  visibility project_visibility not null default 'private',
  published_at timestamptz,          -- public page goes live when set and visibility allows
  theme_id uuid references themes(id) on delete set null,
  theme_overrides jsonb not null default '{}'::jsonb,
  page_blocks jsonb not null default '[]'::jsonb,   -- hand-built public page sections, in order
  stats jsonb not null default '{}'::jsonb,          -- "days in -30", "km hiked", fun numbers
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, slug)
);
create trigger projects_updated before update on projects for each row execute function set_updated_at();
create index projects_org_idx on projects(org_id, division_id);
create index projects_public_idx on projects(org_id, visibility) where published_at is not null;

create table project_members (
  project_id uuid not null references projects(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role project_role not null default 'crew',
  departments text[] not null default '{}',
  title text,                         -- "1st AC", "Backend lead"
  added_by uuid references auth.users(id) on delete set null,
  added_at timestamptz not null default now(),
  primary key (project_id, user_id)
);
create index project_members_user_idx on project_members(user_id);

-- ---------------------------------------------------------------------------
-- Credits: who did what. Clicking a credited person on a public page opens
-- their filmography, which is just their credits on public projects.
-- ---------------------------------------------------------------------------

create table credits (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  person_id uuid not null references people(id) on delete cascade,
  department text not null,          -- directing, writing, cast, camera, sound, dev, ...
  job text not null,                 -- "Director", "Drone pilot", "Frontend"
  character_name text,               -- cast only
  billing int not null default 100,  -- lower sorts first
  note text,                         -- "uncredited", "episodes 1-3", a fun aside
  is_public boolean not null default true,
  created_at timestamptz not null default now()
);
create index credits_project_idx on credits(project_id, department, billing);
create index credits_person_idx on credits(person_id);

-- ---------------------------------------------------------------------------
-- The real side of a production
-- ---------------------------------------------------------------------------

create type media_kind as enum ('still', 'bts', 'blooper', 'poster', 'concept', 'video', 'screenshot', 'audio');

create table media (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  kind media_kind not null default 'still',
  storage_path text,                 -- in the 'public-media' or 'project-files' bucket
  external_url text,                 -- or YouTube/Vimeo/etc.
  caption text,
  story text,                        -- the longer "what happened here"
  taken_at date,
  location text,
  photographer_id uuid references people(id) on delete set null,
  width int, height int, blurhash text,
  sort int not null default 0,
  is_public boolean not null default false,
  uploaded_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  check (storage_path is not null or external_url is not null)
);
create index media_project_idx on media(project_id, kind, sort);

-- People tagged in a photo or blooper, so it shows on their profile too.
create table media_people (
  media_id uuid not null references media(id) on delete cascade,
  person_id uuid not null references people(id) on delete cascade,
  primary key (media_id, person_id)
);

create type trivia_kind as enum ('trivia', 'goof', 'quote', 'fun_fact', 'confession');

create table trivia (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  kind trivia_kind not null default 'trivia',
  body text not null,
  person_id uuid references people(id) on delete set null,  -- who said it / who it's about
  sort int not null default 0,
  is_public boolean not null default false,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create index trivia_project_idx on trivia(project_id, sort);

-- Diary of the production: dated moments with text and media, the timeline
-- of a shoot or a build. The public page can show them as a journey.
create table moments (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  happened_on date not null default current_date,
  title text not null,
  body text,
  media_ids uuid[] not null default '{}',
  mood text,                         -- emoji or short word
  is_public boolean not null default false,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create index moments_project_idx on moments(project_id, happened_on);

-- Podcast episodes about a project: hosted by us or linked from elsewhere.
create table podcast_episodes (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  project_id uuid references projects(id) on delete cascade,   -- null = general episode
  title text not null,
  description text,
  source text not null check (source in ('internal', 'spotify', 'youtube', 'apple', 'soundcloud', 'other')),
  storage_path text,                 -- internal audio/video in 'public-media'
  external_url text,
  duration_seconds int,
  episode_number int,
  cover_url text,
  published_at timestamptz,
  is_public boolean not null default false,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  check ((source = 'internal' and storage_path is not null) or (source <> 'internal' and external_url is not null))
);
create index podcast_project_idx on podcast_episodes(project_id, published_at desc);

create table podcast_guests (
  episode_id uuid not null references podcast_episodes(id) on delete cascade,
  person_id uuid not null references people(id) on delete cascade,
  role text not null default 'guest' check (role in ('host', 'guest')),
  primary key (episode_id, person_id)
);

-- ---------------------------------------------------------------------------
-- Internal documents and outside links
-- ---------------------------------------------------------------------------

-- A document is a file we store, a plain link, or a pointer into Screenplay
-- Studio or Graphite. min_role and departments control who sees it, so cast
-- get the sides and call sheets but not the budget.
create table documents (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  title text not null,
  category text not null default 'general',  -- script, schedule, callsheet, budget, contract, spec, ...
  source text not null check (source in ('upload', 'link', 'screenplay_studio', 'graphite')),
  storage_path text,
  url text,
  external_id text,                  -- SPS script/document id, Graphite page id
  min_role project_role not null default 'crew',
  departments text[] not null default '{}',  -- empty = every department
  pinned boolean not null default false,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (storage_path is not null or url is not null or external_id is not null)
);
create trigger documents_updated before update on documents for each row execute function set_updated_at();
create index documents_project_idx on documents(project_id, category);

-- A project linked to a Screenplay Studio project or a Graphite workspace/page.
-- The portal reads from those apps server-side with the viewer's own token
-- (see user_connections), so it never shows more than the person could see there.
create table project_links (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  provider text not null check (provider in ('screenplay_studio', 'graphite', 'cinderra', 'castingcall', 'github', 'other')),
  external_id text not null,
  external_url text,
  label text,
  min_role project_role not null default 'crew',
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (project_id, provider, external_id)
);

-- Per-user tokens for SPS / Graphite. Server-only: RLS on, no policies, and
-- the token is encrypted by the app (AES-GCM, key in env) before it lands here.
create table user_connections (
  user_id uuid not null references auth.users(id) on delete cascade,
  provider text not null check (provider in ('screenplay_studio', 'graphite')),
  token_ciphertext text not null,
  external_user_label text,
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  primary key (user_id, provider)
);

-- >>> migrations/0003_inbound_invites_press.sql
-- Everything that comes in from the public sites (contact, pitches,
-- applications, casting), the invites that bring people onto the platform,
-- press kits, notifications and the audit log.

-- ---------------------------------------------------------------------------
-- Openings: jobs, casting calls, collaborations. Shown on the division sites.
-- ---------------------------------------------------------------------------

create table openings (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  division_id uuid references divisions(id) on delete set null,
  project_id uuid references projects(id) on delete set null,
  kind text not null check (kind in ('job', 'crew', 'casting', 'collab', 'internship')),
  title text not null,
  body text,
  location text,
  closes_at timestamptz,
  questions jsonb not null default '[]'::jsonb,   -- extra form fields [{id, label, type, required}]
  is_open boolean not null default true,
  is_public boolean not null default false,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger openings_updated before update on openings for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------
-- Submissions: every public form lands here (contact, pitch, application,
-- casting, collab, press request, newsletter). The admin inbox reads this.
-- Inserted only by server actions (service role) after validation, rate
-- limiting and a bot check, so the anon key never touches it.
-- ---------------------------------------------------------------------------

create type submission_status as enum ('new', 'reviewing', 'shortlisted', 'replied', 'accepted', 'declined', 'spam', 'archived');

create table submissions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  division_id uuid references divisions(id) on delete set null,
  opening_id uuid references openings(id) on delete set null,
  form text not null check (form in ('contact', 'pitch', 'application', 'casting', 'collab', 'press', 'newsletter', 'client')),
  name text,
  email citext not null,
  phone text,
  subject text,
  message text,
  payload jsonb not null default '{}'::jsonb,   -- answers, links, budget range, etc.
  attachments text[] not null default '{}',     -- paths in the 'submissions' bucket
  source_host text,                              -- which site it came from
  user_id uuid references auth.users(id) on delete set null,  -- if signed in
  status submission_status not null default 'new',
  assigned_to uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger submissions_updated before update on submissions for each row execute function set_updated_at();
create index submissions_inbox_idx on submissions(org_id, status, created_at desc);

create table submission_notes (
  id uuid primary key default gen_random_uuid(),
  submission_id uuid not null references submissions(id) on delete cascade,
  author_id uuid references auth.users(id) on delete set null,
  body text not null,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Invites. Adding someone by email to the org or a project:
--   * email belongs to an existing user -> the server adds them directly and
--     sends a "you've been added" mail (no invite row needed).
--   * otherwise -> an invite row plus a Resend mail with a one-time link to
--     portal/invite/<token>, where they sign up, build their profile, and
--     accept_invite() wires up membership, project role and their person/credits.
-- Only the SHA-256 of the token is stored.
-- ---------------------------------------------------------------------------

create table invites (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  email citext not null,
  token_hash text not null unique,
  org_role org_role not null default 'guest',
  project_id uuid references projects(id) on delete cascade,
  project_role project_role,
  departments text[] not null default '{}',
  title text,
  person_id uuid references people(id) on delete set null,   -- the credited person they'll become
  message text,
  invited_by uuid references auth.users(id) on delete set null,
  expires_at timestamptz not null default now() + interval '14 days',
  accepted_at timestamptz,
  accepted_by uuid references auth.users(id) on delete set null,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  check ((project_id is null) = (project_role is null))
);
create index invites_email_idx on invites(org_id, email) where accepted_at is null and revoked_at is null;

-- ---------------------------------------------------------------------------
-- Press kits: per project or org-wide. 'press' audience needs the Press role
-- (or higher); 'public' is downloadable from the site.
-- ---------------------------------------------------------------------------

create table press_kits (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  project_id uuid references projects(id) on delete cascade,
  title text not null,
  summary text,
  audience text not null default 'press' check (audience in ('press', 'public')),
  embargo_until timestamptz,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger press_kits_updated before update on press_kits for each row execute function set_updated_at();

create table press_kit_items (
  id uuid primary key default gen_random_uuid(),
  kit_id uuid not null references press_kits(id) on delete cascade,
  title text not null,
  kind text not null default 'file' check (kind in ('file', 'image', 'video', 'text', 'link')),
  storage_path text,       -- in the 'press' bucket
  url text,
  body text,
  sort int not null default 0
);

-- ---------------------------------------------------------------------------
-- Notifications (in-app + push) and devices for the future mobile app
-- ---------------------------------------------------------------------------

create table notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  org_id uuid references orgs(id) on delete cascade,
  kind text not null,              -- added_to_project, credit_added, mention, submission, ...
  title text not null,
  body text,
  href text,
  data jsonb not null default '{}'::jsonb,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index notifications_user_idx on notifications(user_id, created_at desc);

create table devices (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  platform text not null check (platform in ('ios', 'android', 'web')),
  push_token text not null,
  app_version text,
  last_seen_at timestamptz not null default now(),
  unique (platform, push_token)
);

-- ---------------------------------------------------------------------------
-- Audit log: admin actions. Written by the server and by triggers.
-- ---------------------------------------------------------------------------

create table audit_log (
  id bigint generated always as identity primary key,
  org_id uuid references orgs(id) on delete cascade,
  actor_id uuid references auth.users(id) on delete set null,
  action text not null,
  target_table text,
  target_id text,
  detail jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index audit_org_idx on audit_log(org_id, created_at desc);

-- >>> migrations/0004_chat.sql
-- Chat: org channels, project channels, group chats and DMs, with threads,
-- reactions and read markers. Realtime via Supabase Realtime (postgres_changes
-- on chat_messages, filtered by channel_id; RLS applies to realtime too).

create table chat_channels (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  project_id uuid references projects(id) on delete cascade,
  kind text not null check (kind in ('channel', 'project', 'group', 'dm')),
  name text,
  topic text,
  -- Open channels: anyone at or above min role may join/read.
  -- Private channels, groups and DMs: chat_members only.
  is_private boolean not null default false,
  min_org_role org_role not null default 'crew',
  min_project_role project_role not null default 'cast',
  archived_at timestamptz,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  last_message_at timestamptz,
  check (kind <> 'project' or project_id is not null),
  check (kind not in ('group', 'dm') or is_private)
);
create index chat_channels_org_idx on chat_channels(org_id, kind);
create index chat_channels_project_idx on chat_channels(project_id);

create table chat_members (
  channel_id uuid not null references chat_channels(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  is_admin boolean not null default false,
  muted boolean not null default false,
  last_read_at timestamptz not null default now(),
  joined_at timestamptz not null default now(),
  primary key (channel_id, user_id)
);
create index chat_members_user_idx on chat_members(user_id);

create table chat_messages (
  id uuid primary key default gen_random_uuid(),
  channel_id uuid not null references chat_channels(id) on delete cascade,
  author_id uuid references auth.users(id) on delete set null,
  body text not null default '',
  attachments jsonb not null default '[]'::jsonb,   -- [{path, name, mime, size}] in 'chat' bucket
  thread_root_id uuid references chat_messages(id) on delete cascade,
  reply_count int not null default 0,
  mentions uuid[] not null default '{}',
  edited_at timestamptz,
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  check (length(body) <= 20000)
);
create index chat_messages_channel_idx on chat_messages(channel_id, created_at desc);
create index chat_messages_thread_idx on chat_messages(thread_root_id, created_at) where thread_root_id is not null;

create table chat_reactions (
  message_id uuid not null references chat_messages(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  emoji text not null check (length(emoji) <= 32),
  created_at timestamptz not null default now(),
  primary key (message_id, user_id, emoji)
);

-- Keep last_message_at and reply_count current.
create or replace function chat_after_message() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update chat_channels set last_message_at = new.created_at where id = new.channel_id;
  if new.thread_root_id is not null then
    update chat_messages set reply_count = reply_count + 1 where id = new.thread_root_id;
  end if;
  return new;
end $$;
create trigger chat_messages_after_insert after insert on chat_messages
  for each row execute function chat_after_message();

-- One DM channel per pair, created or found atomically.
create table chat_dm_pairs (
  org_id uuid not null references orgs(id) on delete cascade,
  user_a uuid not null references auth.users(id) on delete cascade,
  user_b uuid not null references auth.users(id) on delete cascade,
  channel_id uuid not null references chat_channels(id) on delete cascade,
  primary key (org_id, user_a, user_b),
  check (user_a < user_b)
);

-- >>> migrations/0005_access.sql
-- Access control: helper functions, guard triggers, row-level security, and
-- the few server-side RPCs (accept an invite, open a DM).
--
-- The rules in one paragraph:
--   * Org role (guest < press < cast < crew < producer < admin < owner) decides
--     what someone sees across the org. Admins and owners act as project lead
--     everywhere; so does anyone with the projects.manage_all permission.
--   * Project role (guest < cast < crew < head < lead) decides what someone
--     sees inside a project. Documents and links carry a min_role and optional
--     departments, so a cast member gets sides and call sheets, not budgets.
--   * Public pages read only rows that are is_public on projects that are
--     published as public/unlisted. The anon key sees nothing else.
--   * Forms, invites and integration tokens are written only by the server
--     (service role), which validates, rate-limits and sends mail via Resend.
--
-- Helpers are SECURITY DEFINER so policies can call them without recursing
-- through RLS on the tables they read.

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

create or replace function my_org_role(p_org uuid) returns org_role
language sql stable security definer set search_path = public as $$
  select role from org_members
  where org_id = p_org and user_id = auth.uid() and status = 'active';
$$;

create or replace function org_role_at_least(p_org uuid, p_role org_role) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(my_org_role(p_org) >= p_role, false);
$$;

create or replace function has_perm(p_org uuid, p_perm text) returns boolean
language sql stable security definer set search_path = public as $$
  select case
    when my_org_role(p_org) is null then false
    when my_org_role(p_org) = 'owner' then true
    else exists (select 1 from role_permissions
                 where org_id = p_org and role = my_org_role(p_org) and perm = p_perm)
  end;
$$;

-- True when the two users share an active org (used for profile visibility).
create or replace function shares_org(p_user uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from org_members a join org_members b on a.org_id = b.org_id
    where a.user_id = auth.uid() and b.user_id = p_user
      and a.status = 'active' and b.status = 'active');
$$;

create or replace function project_org(p_project uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select org_id from projects where id = p_project;
$$;

-- Effective project role: org admins / manage_all act as lead.
create or replace function my_project_role(p_project uuid) returns project_role
language sql stable security definer set search_path = public as $$
  select case
    when org_role_at_least(project_org(p_project), 'admin')
      or has_perm(project_org(p_project), 'projects.manage_all') then 'lead'::project_role
    else (select pm.role from project_members pm
          join org_members om on om.org_id = project_org(p_project) and om.user_id = pm.user_id
          where pm.project_id = p_project and pm.user_id = auth.uid() and om.status = 'active')
  end;
$$;

create or replace function project_role_at_least(p_project uuid, p_role project_role) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(my_project_role(p_project) >= p_role, false);
$$;

create or replace function my_project_departments(p_project uuid) returns text[]
language sql stable security definer set search_path = public as $$
  select coalesce((select departments from project_members
                   where project_id = p_project and user_id = auth.uid()), '{}');
$$;

-- Public page is live.
create or replace function project_is_public(p_project uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from projects
    where id = p_project and visibility in ('public', 'unlisted')
      and published_at is not null and published_at <= now());
$$;

-- Can see the project inside portal: members, or crew+ for non-private projects.
create or replace function can_view_project(p_project uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select my_project_role(p_project) is not null
      or exists (select 1 from projects p where p.id = p_project
                 and p.visibility <> 'private' and org_role_at_least(p.org_id, 'crew'));
$$;

-- Role + department gate for documents and links. Leads skip department checks.
create or replace function can_read_gated(p_project uuid, p_min project_role, p_depts text[]) returns boolean
language sql stable security definer set search_path = public as $$
  select project_role_at_least(p_project, p_min)
     and (cardinality(p_depts) = 0
          or project_role_at_least(p_project, 'lead')
          or my_project_departments(p_project) && p_depts);
$$;

create or replace function can_read_channel(p_channel uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from chat_channels c where c.id = p_channel and (
      exists (select 1 from chat_members m where m.channel_id = c.id and m.user_id = auth.uid()
              and org_role_at_least(c.org_id, 'guest'))
      or (not c.is_private and c.kind = 'channel' and org_role_at_least(c.org_id, c.min_org_role))
      or (not c.is_private and c.kind = 'project' and project_role_at_least(c.project_id, c.min_project_role))
    ));
$$;

create or replace function can_moderate_channel(p_channel uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from chat_channels c where c.id = p_channel and (
      (c.kind in ('channel', 'project') and has_perm(c.org_id, 'chat.moderate'))
      or (c.kind = 'project' and project_role_at_least(c.project_id, 'lead'))
      or exists (select 1 from chat_members m where m.channel_id = c.id
                 and m.user_id = auth.uid() and m.is_admin)
    ));
$$;

-- ---------------------------------------------------------------------------
-- Guard triggers (things a policy can't express: who may grant what)
-- auth.uid() is null for the service role and SQL editor, which skip guards.
-- ---------------------------------------------------------------------------

create or replace function org_members_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  actor org_role;
  owners int;
begin
  if auth.uid() is null then return coalesce(new, old); end if;
  actor := my_org_role(coalesce(new.org_id, old.org_id));

  -- Leaving: anyone may remove themselves, except the last owner.
  if tg_op = 'DELETE' and old.user_id = auth.uid() and old.role <> 'owner' then return old; end if;

  -- Accepting an invite: you may add yourself up to the invited role.
  if tg_op in ('INSERT', 'UPDATE') and new.user_id = auth.uid() and exists (
       select 1 from invites i
       where i.org_id = new.org_id and lower(i.email::text) = lower(coalesce(auth.jwt()->>'email', ''))
         and i.accepted_at is null and i.revoked_at is null and i.expires_at > now()
         and (i.org_role >= new.role or (tg_op = 'UPDATE' and new.role = old.role))) then
    return new;
  end if;

  if actor is null then raise exception 'not a member of this org'; end if;
  if actor <> 'owner' then
    -- Non-owners can only touch people below them and grant roles below their own.
    if tg_op in ('UPDATE', 'DELETE') and old.role >= actor then
      raise exception 'you cannot change someone at or above your own role';
    end if;
    if tg_op in ('INSERT', 'UPDATE') and new.role >= actor then
      raise exception 'you cannot grant a role at or above your own';
    end if;
  end if;

  if tg_op in ('UPDATE', 'DELETE') and old.role = 'owner'
     and (tg_op = 'DELETE' or new.role <> 'owner' or new.status <> 'active') then
    select count(*) into owners from org_members
      where org_id = old.org_id and role = 'owner' and status = 'active';
    if owners <= 1 then raise exception 'an org needs at least one owner'; end if;
  end if;
  if tg_op = 'UPDATE' and (new.org_id <> old.org_id or new.user_id <> old.user_id) then
    raise exception 'membership cannot be moved';
  end if;
  return coalesce(new, old);
end $$;
create trigger org_members_guard before insert or update or delete on org_members
  for each row execute function org_members_guard();

create or replace function project_members_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return coalesce(new, old); end if;
  if tg_op = 'DELETE' and old.user_id = auth.uid() then return old; end if;  -- leave
  if tg_op in ('INSERT', 'UPDATE') then
    -- Project members must already belong to the org (invites handle newcomers).
    if not exists (select 1 from org_members where org_id = project_org(new.project_id)
                   and user_id = new.user_id and status = 'active') then
      raise exception 'add this person to the org first, or send them an invite';
    end if;
    if tg_op = 'UPDATE' and (new.project_id <> old.project_id or new.user_id <> old.user_id) then
      raise exception 'membership cannot be moved';
    end if;
  end if;
  return coalesce(new, old);
end $$;
create trigger project_members_guard before insert or update or delete on project_members
  for each row execute function project_members_guard();

-- A linked person may edit their own public bio, photo and links, but not
-- which account or org the person belongs to.
create or replace function people_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or has_perm(old.org_id, 'people.manage') then return new; end if;
  if new.org_id <> old.org_id or new.profile_id is distinct from old.profile_id or new.slug <> old.slug then
    raise exception 'only people managers can relink or rename a person';
  end if;
  return new;
end $$;
create trigger people_guard before update on people for each row execute function people_guard();

-- Chat authors may edit body/attachments or soft-delete; nothing else moves.
create or replace function chat_messages_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;
  if new.channel_id <> old.channel_id or new.author_id is distinct from old.author_id
     or new.created_at <> old.created_at or new.thread_root_id is distinct from old.thread_root_id then
    raise exception 'message cannot be moved';
  end if;
  if new.reply_count <> old.reply_count then new.reply_count := old.reply_count; end if;
  if old.author_id is distinct from auth.uid() then
    -- moderators may only soft-delete
    if new.body <> old.body or new.attachments <> old.attachments then
      raise exception 'only the author can edit a message';
    end if;
  elsif new.body <> old.body then
    new.edited_at := now();
  end if;
  return new;
end $$;
create trigger chat_messages_guard before update on chat_messages
  for each row execute function chat_messages_guard();

-- New project: creator becomes lead, and the project gets its crew channel.
create or replace function projects_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.created_by is not null then
    insert into project_members (project_id, user_id, role, added_by)
    values (new.id, new.created_by, 'lead', new.created_by) on conflict do nothing;
  end if;
  insert into chat_channels (org_id, project_id, kind, name, created_by, min_project_role)
  values (new.org_id, new.id, 'project', new.title, new.created_by, 'cast');
  return new;
end $$;
create trigger projects_after_insert after insert on projects
  for each row execute function projects_after_insert();

create or replace function projects_before_insert() returns trigger
language plpgsql as $$
begin
  if auth.uid() is not null then new.created_by := auth.uid(); end if;
  return new;
end $$;
create trigger projects_before_insert before insert on projects
  for each row execute function projects_before_insert();

-- Tell people when they get a credit or a project role.
create or replace function notify_credit() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  uid uuid; ptitle text; porg uuid;
begin
  select profile_id into uid from people where id = new.person_id;
  if uid is null then return new; end if;
  select title, org_id into ptitle, porg from projects where id = new.project_id;
  insert into notifications (user_id, org_id, kind, title, body, data)
  values (uid, porg, 'credit_added', 'You were credited on ' || ptitle, new.job,
          jsonb_build_object('project_id', new.project_id, 'credit_id', new.id));
  return new;
end $$;
create trigger credits_notify after insert on credits for each row execute function notify_credit();

create or replace function notify_project_member() returns trigger
language plpgsql security definer set search_path = public as $$
declare ptitle text; porg uuid;
begin
  if new.user_id = new.added_by then return new; end if;
  select title, org_id into ptitle, porg from projects where id = new.project_id;
  insert into notifications (user_id, org_id, kind, title, data)
  values (new.user_id, porg, 'added_to_project', 'You were added to ' || ptitle,
          jsonb_build_object('project_id', new.project_id, 'role', new.role));
  return new;
end $$;
create trigger project_members_notify after insert on project_members
  for each row execute function notify_project_member();

-- ---------------------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------------------

-- What the invite page shows before sign-up. Reveals nothing without the token.
create or replace function invite_preview(p_token text) returns jsonb
language sql stable security definer set search_path = public, extensions as $$
  select jsonb_build_object(
    'org', o.name, 'org_slug', o.slug, 'branding', o.branding,
    'project', p.title, 'project_role', i.project_role, 'org_role', i.org_role,
    'title', i.title, 'message', i.message,
    'invited_by', pr.display_name, 'email', i.email,
    'person', pe.name, 'expires_at', i.expires_at)
  from invites i
  join orgs o on o.id = i.org_id
  left join projects p on p.id = i.project_id
  left join profiles pr on pr.id = i.invited_by
  left join people pe on pe.id = i.person_id
  where i.token_hash = encode(digest(p_token, 'sha256'), 'hex')
    and i.accepted_at is null and i.revoked_at is null and i.expires_at > now();
$$;

-- Signed-in user redeems an invite sent to their email address.
create or replace function accept_invite(p_token text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  inv invites;
  my_email text := lower(coalesce(auth.jwt()->>'email', ''));
begin
  if auth.uid() is null then raise exception 'sign in first'; end if;
  select * into inv from invites
    where token_hash = encode(digest(p_token, 'sha256'), 'hex') for update;
  if not found or inv.revoked_at is not null then raise exception 'invite not found'; end if;
  if inv.accepted_at is not null then raise exception 'invite already used'; end if;
  if inv.expires_at <= now() then raise exception 'invite expired'; end if;
  if lower(inv.email::text) <> my_email then
    raise exception 'this invite was sent to a different email address';
  end if;

  -- Org membership: keep the higher of existing and invited role.
  insert into org_members (org_id, user_id, role, title, departments)
  values (inv.org_id, auth.uid(), inv.org_role, inv.title, inv.departments)
  on conflict (org_id, user_id) do update
    set role = greatest(org_members.role, excluded.role), status = 'active';

  if inv.project_id is not null then
    insert into project_members (project_id, user_id, role, departments, title, added_by)
    values (inv.project_id, auth.uid(), inv.project_role, inv.departments, inv.title, inv.invited_by)
    on conflict (project_id, user_id) do update
      set role = greatest(project_members.role, excluded.role);
  end if;

  -- Claim the credited person, or create one for them.
  if inv.person_id is not null then
    update people set profile_id = auth.uid()
      where id = inv.person_id and profile_id is null
        and not exists (select 1 from people where org_id = inv.org_id and profile_id = auth.uid());
  end if;

  update invites set accepted_at = now(), accepted_by = auth.uid() where id = inv.id;
  insert into audit_log (org_id, actor_id, action, target_table, target_id)
  values (inv.org_id, auth.uid(), 'invite.accepted', 'invites', inv.id::text);

  return jsonb_build_object('org_id', inv.org_id, 'project_id', inv.project_id);
end $$;

-- Find or create the DM channel between me and another member.
create or replace function open_dm(p_org uuid, p_other uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  a uuid := least(auth.uid(), p_other);
  b uuid := greatest(auth.uid(), p_other);
  ch uuid;
begin
  if auth.uid() is null or p_other = auth.uid() then raise exception 'invalid DM'; end if;
  if not org_role_at_least(p_org, 'cast') then raise exception 'not allowed to start DMs'; end if;
  if not exists (select 1 from org_members where org_id = p_org and user_id = p_other and status = 'active') then
    raise exception 'that person is not in this org';
  end if;
  select channel_id into ch from chat_dm_pairs where org_id = p_org and user_a = a and user_b = b;
  if ch is not null then return ch; end if;
  insert into chat_channels (org_id, kind, is_private, created_by)
    values (p_org, 'dm', true, auth.uid()) returning id into ch;
  insert into chat_members (channel_id, user_id) values (ch, a), (ch, b);
  insert into chat_dm_pairs values (p_org, a, b, ch);
  return ch;
end $$;

revoke execute on function accept_invite(text) from anon;
revoke execute on function open_dm(uuid, uuid) from anon;

-- ---------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------

alter table orgs enable row level security;
alter table org_domains enable row level security;
alter table divisions enable row level security;
alter table profiles enable row level security;
alter table org_members enable row level security;
alter table role_permissions enable row level security;
alter table people enable row level security;
alter table themes enable row level security;
alter table projects enable row level security;
alter table project_members enable row level security;
alter table credits enable row level security;
alter table media enable row level security;
alter table media_people enable row level security;
alter table trivia enable row level security;
alter table moments enable row level security;
alter table podcast_episodes enable row level security;
alter table podcast_guests enable row level security;
alter table documents enable row level security;
alter table project_links enable row level security;
alter table user_connections enable row level security;   -- server only, no policies
alter table openings enable row level security;
alter table submissions enable row level security;
alter table submission_notes enable row level security;
alter table invites enable row level security;
alter table press_kits enable row level security;
alter table press_kit_items enable row level security;
alter table notifications enable row level security;
alter table devices enable row level security;
alter table audit_log enable row level security;
alter table chat_channels enable row level security;
alter table chat_members enable row level security;
alter table chat_messages enable row level security;
alter table chat_reactions enable row level security;
alter table chat_dm_pairs enable row level security;

-- Orgs, domains, divisions: public metadata the sites need to render.
create policy orgs_read on orgs for select using (true);
create policy orgs_update on orgs for update using (org_role_at_least(id, 'admin')) with check (org_role_at_least(id, 'admin'));

create policy domains_read on org_domains for select using (true);
create policy domains_write on org_domains for all using (org_role_at_least(org_id, 'owner')) with check (org_role_at_least(org_id, 'owner'));

create policy divisions_read on divisions for select using (is_public or org_role_at_least(org_id, 'guest'));
create policy divisions_write on divisions for all using (has_perm(org_id, 'sites.edit')) with check (has_perm(org_id, 'sites.edit'));

-- Profiles: public ones to everyone, the rest to colleagues; only you edit yours.
create policy profiles_read on profiles for select using (is_public or id = auth.uid() or shares_org(id));
create policy profiles_insert on profiles for insert with check (id = auth.uid());
create policy profiles_update on profiles for update using (id = auth.uid()) with check (id = auth.uid());

-- Members: cast and up see the team list; guests and press see only themselves.
create policy members_read on org_members for select
  using (user_id = auth.uid() or org_role_at_least(org_id, 'cast'));
create policy members_insert on org_members for insert with check (has_perm(org_id, 'people.manage'));
create policy members_update on org_members for update
  using (has_perm(org_id, 'people.manage')) with check (has_perm(org_id, 'people.manage'));
create policy members_delete on org_members for delete
  using (user_id = auth.uid() or has_perm(org_id, 'people.manage'));

create policy perms_read on role_permissions for select using (org_role_at_least(org_id, 'guest'));
create policy perms_write on role_permissions for all
