       (kind = 'channel' and has_perm(org_id, 'chat.create_channel'))
    or (kind = 'project' and project_role_at_least(project_id, 'head') and project_org(project_id) = org_id)
    or (kind = 'group' and org_role_at_least(org_id, 'cast'))));
create policy channels_update on chat_channels for update
  using (can_moderate_channel(id)) with check (can_moderate_channel(id));
create policy channels_delete on chat_channels for delete
  using (kind <> 'dm' and can_moderate_channel(id));

create policy cmembers_read on chat_members for select using (can_read_channel(channel_id));
-- Join an open channel yourself, or be added by a channel admin/moderator (or
-- the creator of a new group adding the first members).
create policy cmembers_insert on chat_members for insert
  with check (
    (user_id = auth.uid() and can_read_channel(channel_id))
    or (can_moderate_channel(channel_id)
        and exists (select 1 from chat_channels c join org_members m on m.org_id = c.org_id
                    where c.id = channel_id and c.kind <> 'dm' and m.user_id = chat_members.user_id and m.status = 'active'))
    or exists (select 1 from chat_channels c join org_members m on m.org_id = c.org_id
               where c.id = channel_id and c.kind = 'group' and c.created_by = auth.uid()
                 and m.user_id = chat_members.user_id and m.status = 'active'));
create policy cmembers_update on chat_members for update
  using (user_id = auth.uid() or can_moderate_channel(channel_id))
  with check (user_id = auth.uid() or can_moderate_channel(channel_id));
create policy cmembers_delete on chat_members for delete
  using (user_id = auth.uid() or can_moderate_channel(channel_id));

create policy messages_read on chat_messages for select using (can_read_channel(channel_id));
create policy messages_insert on chat_messages for insert
  with check (author_id = auth.uid() and can_read_channel(channel_id)
              and exists (select 1 from chat_channels c where c.id = channel_id and c.archived_at is null)
              and (thread_root_id is null or exists (select 1 from chat_messages r
                   where r.id = thread_root_id and r.channel_id = chat_messages.channel_id)));
create policy messages_update on chat_messages for update
  using (author_id = auth.uid() or can_moderate_channel(channel_id))
  with check (can_read_channel(channel_id));
create policy messages_delete on chat_messages for delete using (can_moderate_channel(channel_id));

create policy reactions_read on chat_reactions for select
  using (exists (select 1 from chat_messages m where m.id = message_id));
create policy reactions_insert on chat_reactions for insert
  with check (user_id = auth.uid() and exists (select 1 from chat_messages m where m.id = message_id));
create policy reactions_delete on chat_reactions for delete using (user_id = auth.uid());

create policy dm_pairs_read on chat_dm_pairs for select using (auth.uid() in (user_a, user_b));

-- Realtime
alter publication supabase_realtime add table chat_messages, chat_reactions, chat_members, chat_channels, notifications;

-- >>> migrations/0006_storage.sql
-- Storage buckets. Paths start with the id that decides access:
--   public-media  <project_id>/...   public read; crew+ upload (rows decide what the site shows)
--   avatars       <user_id>/...      public read; you write your own folder
--   project-files <project_id>/...   private; readable when a documents row for the path is readable
--   press         <kit_id>/...       private unless the kit is public
--   chat          <channel_id>/...   private; channel readers
--   submissions   <submission_id>/... private; server uploads, forms.read downloads

insert into storage.buckets (id, name, public) values
  ('public-media', 'public-media', true),
  ('avatars', 'avatars', true),
  ('project-files', 'project-files', false),
  ('press', 'press', false),
  ('chat', 'chat', false),
  ('submissions', 'submissions', false)
on conflict (id) do nothing;

create or replace function public.storage_first_uuid(p_name text) returns uuid
language plpgsql immutable as $$
begin
  return split_part(p_name, '/', 1)::uuid;
exception when others then
  return null;
end $$;

create policy "public media upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'public-media' and public.project_role_at_least(storage_first_uuid(name), 'crew'));
create policy "public media manage" on storage.objects for delete to authenticated
  using (bucket_id = 'public-media' and public.project_role_at_least(storage_first_uuid(name), 'head'));

create policy "avatar write" on storage.objects for insert to authenticated
  with check (bucket_id = 'avatars' and public.storage_first_uuid(name) = auth.uid());
create policy "avatar update" on storage.objects for update to authenticated
  using (bucket_id = 'avatars' and public.storage_first_uuid(name) = auth.uid());
create policy "avatar delete" on storage.objects for delete to authenticated
  using (bucket_id = 'avatars' and public.storage_first_uuid(name) = auth.uid());

create policy "project files read" on storage.objects for select to authenticated
  using (bucket_id = 'project-files' and exists (
    select 1 from public.documents d where d.storage_path = name
      and public.can_read_gated(d.project_id, d.min_role, d.departments)));
create policy "project files upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'project-files' and public.project_role_at_least(storage_first_uuid(name), 'head'));
create policy "project files delete" on storage.objects for delete to authenticated
  using (bucket_id = 'project-files' and public.project_role_at_least(storage_first_uuid(name), 'lead'));

create policy "press read" on storage.objects for select
  using (bucket_id = 'press' and exists (select 1 from public.press_kits k where k.id = public.storage_first_uuid(name)));
create policy "press write" on storage.objects for insert to authenticated
  with check (bucket_id = 'press' and exists (select 1 from public.press_kits k where k.id = public.storage_first_uuid(name)
    and (public.has_perm(k.org_id, 'sites.edit') or (k.project_id is not null and public.project_role_at_least(k.project_id, 'lead')))));

create policy "chat read" on storage.objects for select to authenticated
  using (bucket_id = 'chat' and public.can_read_channel(storage_first_uuid(name)));
create policy "chat upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'chat' and public.can_read_channel(storage_first_uuid(name)));

create policy "submission files read" on storage.objects for select to authenticated
  using (bucket_id = 'submissions' and exists (select 1 from public.submissions s
    where s.id = public.storage_first_uuid(name) and public.has_perm(s.org_id, 'forms.read')));

-- >>> migrations/0007_server_helpers.sql
-- Server-only helpers used by the apps with the service role.

-- Look up an account by email when adding someone to a project, so we know
-- whether to add them directly or send an invite. Never callable by users.
create or replace function user_id_by_email(p_email text) returns uuid
language sql stable security definer set search_path = public, auth as $$
  select id from auth.users where lower(email) = lower(p_email) limit 1;
$$;
revoke execute on function user_id_by_email(text) from public, anon, authenticated;
grant execute on function user_id_by_email(text) to service_role;

-- Effective project role for the current user, for UI decisions.
create or replace function my_project_role_rpc(p_project uuid) returns project_role
language sql stable security definer set search_path = public as $$
  select my_project_role(p_project);
$$;

-- Unread count per channel for the signed-in user (chat sidebar).
create or replace function chat_unread() returns table (channel_id uuid, unread bigint)
language sql stable security definer set search_path = public as $$
  select m.channel_id, count(msg.id)
  from chat_members m
  join chat_messages msg on msg.channel_id = m.channel_id
   and msg.created_at > m.last_read_at and msg.author_id is distinct from m.user_id and msg.deleted_at is null
  where m.user_id = auth.uid()
  group by m.channel_id;
$$;

-- >>> migrations/0008_org_media.sql
-- Org-level public images: credited people's photos, logos, general podcast
-- episodes. They live in 'public-media' under <org_id>/..., next to the
-- per-project folders, and only people who manage those things can write.

create policy "org media upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'public-media' and exists (
    select 1 from public.orgs o where o.id = public.storage_first_uuid(name)
      and (public.has_perm(o.id, 'sites.edit') or public.has_perm(o.id, 'people.manage')
           or public.has_perm(o.id, 'podcasts.publish') or public.has_perm(o.id, 'projects.create'))));

create policy "org media delete" on storage.objects for delete to authenticated
  using (bucket_id = 'public-media' and exists (
    select 1 from public.orgs o where o.id = public.storage_first_uuid(name)
      and (public.has_perm(o.id, 'sites.edit') or public.has_perm(o.id, 'people.manage'))));

-- The admin lists who is in the org with their email, which profiles don't hold.
create or replace function public.org_member_emails(p_org uuid)
returns table (user_id uuid, email text)
language sql stable security definer set search_path = public as $$
  select u.id, u.email::text from auth.users u
  join org_members m on m.user_id = u.id and m.org_id = p_org
  where has_perm(p_org, 'people.manage') or has_perm(p_org, 'people.invite');
$$;
revoke all on function public.org_member_emails(uuid) from public, anon;
grant execute on function public.org_member_emails(uuid) to authenticated;

-- >>> migrations/0009_insert_readback.sql
-- Creating a project or a chat channel failed with "violates row-level security".
-- The app inserts and reads the new row back in one statement, and Postgres checks
-- the read policy then. The helper functions look the row up by id, and they can't
-- see a row the same statement is still inserting, so the read check said no.
-- These policies now also pass on the row's own columns: the creator can always
-- read what they just made, and so can org admins.

drop policy if exists projects_read on projects;
create policy projects_read on projects for select
  using ((visibility in ('public', 'unlisted') and published_at is not null and published_at <= now())
         or created_by = auth.uid()
         or org_role_at_least(org_id, 'admin')
         or has_perm(org_id, 'projects.manage_all')
         or can_view_project(id));

drop policy if exists channels_read on chat_channels;
create policy channels_read on chat_channels for select
  using (created_by = auth.uid() or can_read_channel(id));

-- >>> seed.sql
-- Seed: Northem as the first org, its four divisions and its hosts.
-- Run after migrations. Make yourself owner afterwards with:
--   insert into org_members (org_id, user_id, role)
--   select id, '<your auth user id>', 'owner' from orgs where slug = 'northem';

insert into orgs (slug, name, branding) values
  ('northem', 'Northem', '{"product_name": "Northem Portal", "mail_from": "Northem <hello@northem.group>"}')
on conflict (slug) do nothing;

with o as (select id from orgs where slug = 'northem')
insert into divisions (org_id, slug, name, tagline, sort, theme)
select o.id, d.slug, d.name, d.tagline, d.sort, d.theme::jsonb from o, (values
  ('productions', 'Northem Productions', 'The parts of people nobody films.', 1, '{"key": "prod"}'),
  ('development', 'Northem Development', 'Tools that get out of the way.', 2, '{"key": "dev"}'),
  ('specprod', 'Specprod', 'Shots from places cameras should not go.', 3, '{"key": "specprod"}'),
  ('sonorthem', 'SoNorthem', 'Made for the feed, built to last.', 4, '{"key": "so"}')
) as d(slug, name, tagline, sort, theme)
on conflict (org_id, slug) do nothing;

with o as (select id from orgs where slug = 'northem')
insert into org_domains (host, org_id, app, division_id, is_primary)
select h.host, o.id, h.app, (select id from divisions where org_id = o.id and slug = h.div), true
from o, (values
  ('northem.group', 'landing', null),
  ('prod.northem.group', 'division', 'productions'),
  ('dev.northem.group', 'division', 'development'),
  ('specprod.northem.group', 'division', 'specprod'),
  ('so.northem.group', 'division', 'sonorthem'),
  ('portal.northem.group', 'portal', null),
  ('admin.northem.group', 'admin', null)
) as h(host, app, div)
on conflict (host) do nothing;

